<?php class DashboardController{function index(){require_login();$db=Database::connect();$stats=['produk'=>$db->query('SELECT COUNT(*) c FROM produk')->fetch()['c'],'transaksi'=>$db->query('SELECT COUNT(*) c FROM transaksi')->fetch()['c'],'pendapatan'=>$db->query('SELECT COALESCE(SUM(total),0) c FROM transaksi')->fetch()['c'],'stok'=>$db->query('SELECT COALESCE(SUM(stok),0) c FROM produk')->fetch()['c']];require __DIR__.'/../views/dashboard/index.php';}}
